#!/usr/bin/env bash
# SO LEITURA -- sombra da V1.1 (Reservas e canais 1.3.0, Dom 21/11 "Alta") ao lado da V1.0, sem instalar nada:
#  (1) o LEITOR do e-mail da V1.1 (copia embutida aqui, so em memoria) contra o da V1.0, nos e-mails do Airbnb de 150
#      dias da caixa (IMAP so leitura: readonly + BODY.PEEK);
#  (2) o ENCAIXE da V1.1 (catalogo por ID + quarto livre) contra a unidade que a V1.0 escolheu em cada reserva criada
#      pelo e-mail, com a ocupacao real da V1.0 (sem contar a propria reserva).
# Saida: so contagens, nomes de campo, ids de anuncio e unidades. Nenhum nome, codigo HM, valor, telefone ou e-mail.
set -u
exec 2>&1
cd /opt/PMS-Banana-AI/SISTEMA/api || exit 1
echo "versao: $(grep -oP 'VERSAO = "\K[^"]+' app/versao.py)"
sudo -n /opt/esteira-nuvem/com-segredos env PMS_TRANSCRICAO_AQUECER=off PYTHONDONTWRITEBYTECODE=1 timeout 900 ../.venv/bin/python -u - <<'PY' 2>&1 | grep -vE '^(WARNING|INFO|DEBUG)'
import base64, email, imaplib, json, os, types
from collections import Counter
from datetime import date, datetime, timedelta, timezone
from email.utils import parseaddr, parsedate_to_datetime
def modulo(nome, b64):
    m = types.ModuleType(nome); exec(compile(base64.b64decode(b64).decode(), nome, "exec"), m.__dict__); return m
A11 = modulo("v11_airbnb_email", "")
C11 = modulo("v11_catalogo", "")
CAT = C11.validar(json.loads(base64.b64decode("").decode()))
from app.main import build_state
from app.entrada import imap_reservas as I, airbnb_email as A10, airbnb_reservas as R10
from app.entrada.intents import classificar as classificar10, ota_do_dominio, casar
st = build_state(); s = st.store; agora = datetime.now(timezone.utc)
# (1) leitor
cfg = I.config(os.environ); print("caixa configurada:", "sim" if cfg else "NAO")
M = imaplib.IMAP4_SSL(cfg["servidor"], 993, timeout=30); M.login(cfg["usuario"], cfg["senha"])
typ, _ = M.select('"INBOX.03_Reservas"', readonly=True)
typ, d = M.search(None, f"(SINCE {(agora - timedelta(days=150)).strftime('%d-%b-%Y')})")
nums = (d[0] or b"").split() if typ == "OK" else []
tipos = Counter(); campos = Counter(); conv = Counter(); difs = Counter(); n_air = 0
for num in nums:
    t, c = M.fetch(num, "(BODY.PEEK[HEADER.FIELDS (FROM)])")
    rem = parseaddr(I._dec(email.message_from_bytes(c[0][1]).get("From")))[1].lower()
    if ota_do_dominio(rem.rsplit("@", 1)[-1]) != "Airbnb": continue
    n_air += 1
    t, c = M.fetch(num, "(BODY.PEEK[])"); em = I.para_porta(c[0][1])
    t10 = classificar10(em["dominio"], em["assunto"], em["texto"]).get("tipo") or "outro"
    t11 = A11.classificar(em["assunto"], em["texto"])
    tipos["tipo igual" if t10 == t11 else f"tipo diferente {t10}->{t11}"] += 1
    if t10 != "reserva_nova": continue
    try: q = parsedate_to_datetime(em["quando"])
    except Exception: q = None
    l10 = A10.ler(em["assunto"], em["texto"], q); l10.pop("_nome", None)
    l11 = A11.ler(em["assunto"], em["texto"], q); l11.pop("_nome", None)
    for k in ("codigo", "checkin", "checkout", "hospedes", "noites", "anuncio_id", "completa", "aviso"):
        if l10.get(k) == l11.get(k): campos[f"{k} igual"] += 1
        else: campos[f"{k} DIFERENTE"] += 1; difs[k] += 1
    r = A11.converter({"dominio": em["dominio"], "assunto": em["assunto"], "texto": em["texto"], "quando": em["quando"]})
    conv["vira reserva" if "reserva" in r else "vai para o alarme" if "alarme" in r else "ignorado"] += 1
M.logout()
print(f"(1) e-mails do Airbnb em 150 dias: {n_air}")
print("    classificacao:", dict(tipos))
print("    reservas novas, campo a campo:", dict(sorted(campos.items())))
print("    V1.1 converter:", dict(conv))
# (2) encaixe
print("(2) ENCAIXE;anuncio;hospedes;v10_unidade_anuncio;v10_escolheu;v11_codigo;v11_escolhe;v11_candidatas")
iguais = difer = 0
for row in sorted((getattr(s, "entradas", {}) or {}).values(), key=lambda r: str(r.get("recebido_em") or "")):
    p = row.get("plano") or {}
    if row.get("ota") != "Airbnb" or p.get("acao") != "criar": continue
    res = casar(s, p.get("codigo") or "")
    sem = res.reservation_id if res is not None else ""
    ci, co = date.fromisoformat(p["checkin"]), date.fromisoformat(p["checkout"])
    prod = C11.resolver(CAT, "airbnb", str(p.get("anuncio_id")))
    if prod is None:
        print(f"ENCAIXE;{p.get('anuncio_id')};{p.get('hospedes')};{p.get('unidade_anuncio')};{p.get('unidade')};-;fora do catalogo;"); difer += 1; continue
    cand = C11.candidatas(CAT, prod, p.get("hospedes"))
    conf = C11.conflitos(CAT, cand)
    escolhe = next((u for u in cand if not R10.ocupantes(s, u, ci, co, sem=sem)
                    and not any(R10.ocupantes(s, x, ci, co, sem=sem) for x in conf.get(u, []))), "SEM VAGA")
    ok = escolhe == p.get("unidade"); iguais += ok; difer += not ok
    print(f"ENCAIXE;{p.get('anuncio_id')};{p.get('hospedes')};{p.get('unidade_anuncio')};{p.get('unidade')};{prod['codigo']};{escolhe};{'|'.join(cand)}")
print(f"    encaixe: {iguais} iguais, {difer} diferentes")
# (3) as candidatas dos 59 anuncios: V1.0 x V1.1 (sem ocupacao)
from app.entrada.anuncios_airbnb import TABELA
mesmo = ordem = alcance = 0
for aid, (un, categ, ver) in sorted(TABELA.items()):
    prod = C11.resolver(CAT, "airbnb", aid)
    if prod is None or not prod["sozinho"] or categ not in getattr(__import__("app.entrada.anuncios_airbnb", fromlist=["x"]), "CATEGORIAS"): continue
    c10 = R10.candidatas(un, categ); c11 = C11.candidatas(CAT, prod, 1)
    if c10 == c11: mesmo += 1
    elif set(c10) == set(c11): ordem += 1
    else:
        alcance += 1
        print(f"CANDIDATAS;{aid};{prod['codigo']};so_v10={'|'.join(u for u in c10 if u not in c11)};so_v11={'|'.join(u for u in c11 if u not in c10)}")
print(f"(3) candidatas por anuncio (1 hospede): {mesmo} iguais, {ordem} mesma lista em outra ordem, {alcance} com alcance diferente")
PY
echo "fim"
